function buildBerryTasteByKey(game: GameRuntime, now: number): Record<string, FeticheTaste | null> {
    if (!game.unlockedFeatures?.fetiche || !game.feticheState?.speciesKey) {
        return {};
    }
    const state = normalizeFeticheState(game.feticheState, now);
    const types = getSpeciesElementTypes(state.speciesKey);
    const board = buildFeticheTasteBoard(state, types, now);
    const out: Record<string, FeticheTaste | null> = {};
    for (const berryKey of BERRY_DEX_KEYS) {
        out[berryKey] = board[berryKey] ?? null;
    }
    return out;
}

function buildPlantQueueMeta(
    berryTree: BerryTreeState,
    berryKey: string,
    plantQueueKeys: readonly string[] = berryTree.plantQueue,
): { canQueue: boolean; isQueued: boolean; queuedCount: number } {
    const queuedCount = plantQueueKeys.filter((k) => k === berryKey).length;
    const queueHasRoom = plantQueueKeys.length < berryTree.plantQueueLevel;
    return {
        canQueue: berryTree.plantQueueLevel > 0
            && berryTree.activeCrop?.berryKey !== berryKey
            && (queueHasRoom || berryTree.plantQueueLevel === 1),
        isQueued: queuedCount > 0,
        queuedCount,
    };
}

function buildAlmanacEntries(
    game: GameRuntime,
    berryTree: BerryTreeState,
    berryTasteByKey: Record<string, FeticheTaste | null>,
): BerryTreeAlmanacEntrySnapshot[] {
    return [...BERRY_DEX_KEYS].sort(compareBerryKeysByProductionTier).map((berryKey) => {
        const recipe = getBerryTreeRecipe(berryKey);
        const revealed = berryTree.revealedSlotsByBerry[berryKey] ?? [];
        const ingredients = recipe?.ingredients ?? [];
        const unlocked = berryTree.unlockedBerryKeys.includes(berryKey);
        const overlay = buildFeticheBerryOverlay(berryKey, berryTasteByKey[berryKey] ?? null);
        const queueMeta = unlocked
            ? buildPlantQueueMeta(berryTree, berryKey)
            : { canQueue: false, isQueued: false, queuedCount: 0 };
        return {
            berryKey,
            name: itemLabel(game, berryKey),
            berryIconUrl: itemIconUrl(berryKey),
            unlocked,
            canPlant: unlocked,
            isActiveCrop: berryTree.activeCrop?.berryKey === berryKey,
            canQueue: queueMeta.canQueue,
            isQueued: queueMeta.isQueued,
            queuedCount: queueMeta.queuedCount,
            feticheTaste: berryTasteByKey[berryKey] ?? null,
            feticheStatHint: overlay.statHint,
            feticheStatEffect: overlay.statEffect,
            berryDescription: itemDescription(game, berryKey),
            recipeSlots: ingredients.map((ingredient, i) => {
                const itemKey = revealed[i];
                const revealedSlot = itemKey === ingredient;
                return {
                    revealed: revealedSlot,
                    itemKey: revealedSlot ? itemKey : null,
                    itemIconUrl: revealedSlot ? itemIconUrl(itemKey) : null,
                    itemName: revealedSlot ? itemLabel(game, itemKey!) : null,
                    itemDescription: revealedSlot ? itemDescription(game, itemKey!) : null,
                };
            }),
        };
    });
}

function buildEligibleItemGroups(game: GameRuntime): BerryTreeCombineEligibleGroupSnapshot[] {
    const items = game.items ?? {};
    const eligibleCounts: Record<string, number> = {};
    for (const [itemKey, count] of Object.entries(items)) {
        const qty = Math.max(0, Math.floor(Number(count) || 0));
        if (qty <= 0) continue;
        if (!isBerryCombineEligibleItemKey(itemKey)) continue;
        eligibleCounts[itemKey] = qty;
    }

    const getItemDef = (itemKey: string): TowerLootItemDef | null => {
        const item = ALL_ITEMS[itemKey as keyof typeof ALL_ITEMS];
        return item ?? null;
    };
    const getSortLabel = (itemKey: string) => itemLabel(game, itemKey);

    return groupTowerLootItems(eligibleCounts, getItemDef, getSortLabel).map((group) => ({
        category: group.category,
        categoryLabel: bagInventoryCategoryLabel(game, group.category),
        items: group.items.map((entry): BerryTreeCombineEligibleItemSnapshot => ({
            itemKey: entry.itemKey,
            displayName: itemLabel(game, entry.itemKey),
            iconUrl: itemIconUrl(entry.itemKey),
            count: entry.count,
        })),
    }));
}

function buildCombineSlotSnapshots(
    game: GameRuntime,
    slots: readonly (string | null)[],
): BerryTreeSnapshot['combineDraft'] {
    return slots.map((itemKey, slotIndex) => ({
        slotIndex,
        itemKey,
        itemIconUrl: itemIconUrl(itemKey),
        itemName: itemKey ? itemLabel(game, itemKey) : null,
    }));
}

function buildCombineSlotSnapshotsFromSubmitted(
    game: GameRuntime,
    submitted: readonly string[],
): BerryTreeSnapshot['combinePendingSlots'] {
    return submitted.map((raw, slotIndex) => {
        const itemKey = raw && raw.length > 0 ? raw : null;
        return {
            slotIndex,
            itemKey,
            itemIconUrl: itemIconUrl(itemKey),
            itemName: itemKey ? itemLabel(game, itemKey) : null,
        };
    });
}

function getLang(game: GameRuntime): 'fr' | 'en' {
    const lang = typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    return lang === 'en' ? 'en' : 'fr';
}

function formatBerryProductionRateLabel(
    game: GameRuntime,
    ui: BerryTreeUiSnapshot,
    berryKey: string,
    productionMult: number,
): string {
    const displayRate = getBerryDisplayBerriesPerHour(berryKey, productionMult);
    if (displayRate >= 1) {
        const rounded = displayRate % 1 === 0
            ? String(displayRate)
            : displayRate.toFixed(1).replace(/\.0$/, '');
        return `${rounded}${ui.perHour}`;
    }
    if (displayRate > 0) {
        const msPerBerry = (1 / displayRate) * 3_600_000;
        return farmT(
            game,
            'berryTree.productionRatePerBerry',
            '1 baie / ~{time}',
            '1 berry / ~{time}',
            { time: formatFarmDuration(msPerBerry, getLang(game)) },
        );
    }
    return '—';
}

function buildCropSnapshot(
    game: GameRuntime,
    berryTree: BerryTreeState,
    now: number,
    ui: BerryTreeUiSnapshot,
): BerryTreeCropSnapshot | null {
    const crop = berryTree.activeCrop;
    if (!crop?.berryKey) return null;
    const productionMult = getBerryProductionMult(berryTree, now);
    const timeReduction = game.getMasteryBonus?.('berry_production_time_reduction') || 0;
    const timeMult = timeReduction > 0 && timeReduction < 1 ? 1 / (1 - Math.min(0.5, timeReduction)) : 1;
    const effectiveMult = productionMult * timeMult;
    const displayRate = getBerryDisplayBerriesPerHour(crop.berryKey, effectiveMult);
    const cap = Math.max(1, Math.floor(Number(crop.stockCap) || 1));
    const stored = Math.max(0, Math.floor(Number(crop.storedQty) || 0));
    const pending = Math.max(0, Number(crop.pendingFraction) || 0);
    const fillPct = cap > 0 ? Math.min(100, Math.round(((stored + pending) / cap) * 100)) : 0;
    const productionComplete = !!crop.productionComplete || stored >= cap;
    const productionRateLabel = formatBerryProductionRateLabel(game, ui, crop.berryKey, effectiveMult);
    let productionEtaLabel: string | null = null;
    let productionDoneLabel: string | null = null;
    if (productionComplete) {
        productionDoneLabel = ui.productionDone;
    } else if (displayRate > 0 && stored < cap) {
        const remaining = Math.max(0, cap - stored - pending);
        const hoursToFull = remaining / displayRate;
        productionEtaLabel = farmT(
            game,
            'berryTree.productionReadyIn',
            'Prête dans ~{time}',
            'Ready in ~{time}',
            { time: formatFarmDuration(hoursToFull * 3_600_000, getLang(game)) },
        );
    }
    return {
        berryKey: crop.berryKey,
        berryName: itemLabel(game, crop.berryKey),
        berryIconUrl: itemIconUrl(crop.berryKey),
        storedQty: stored,
        stockCap: cap,
        berriesPerHour: displayRate,
        productionRateLabel,
        productionEtaLabel,
        productionDoneLabel,
        productionComplete,
        fillPct,
        canClaim: stored > 0,
    };
}

export function buildBerryTreeSnapshot(
    game: GameRuntime,
    berryTree: BerryTreeState,
    farmState?: MiltankFarmState | null,
): BerryTreeSnapshot {
    const now = Date.now();
    const ui = buildUi(game);
    const berryTasteByKey = buildBerryTasteByKey(game, now);
    const feticheTasteHint = game.feticheState?.speciesKey ? ui.feticheTasteHint : null;
    const boostUntil = Math.max(0, Number(berryTree.productionBoostUntil) || 0);
    const fertilizerActive = boostUntil > now;
    const boostRemainingMs = fertilizerActive ? boostUntil - now : 0;
    const bonusBerryChanceActive = getBerryBonusBerryChance(berryTree, now);
    const productionMult = getBerryProductionMult(berryTree, now);
    let boostEffectDetailLabel: string | null = null;
    if (fertilizerActive) {
        if (bonusBerryChanceActive > 0) {
            boostEffectDetailLabel = farmT(
                game,
                'berryTree.boostBonusChance',
                '+{pct} % baie bonus',
                '+{pct}% bonus berry',
                { pct: Math.round(bonusBerryChanceActive * 100) },
            );
        } else if (productionMult > 1) {
            boostEffectDetailLabel = farmT(
                game,
                'berryTree.boostSpeedMult',
                '×{mult} vitesse de production',
                '×{mult} production speed',
                { mult: productionMult % 1 === 0 ? productionMult : productionMult.toFixed(2) },
            );
        }
    }
    const unlockedCount = berryTree.unlockedBerryKeys.length;
    const totalCount = BERRY_DEX_KEYS.length;
    const draftFilled = berryTree.combineDraft.some((s) => !!s);
    const combineProgress = getBerryCombineProgress(berryTree, now);
    const combineInProgress = combineProgress.inProgress;
    const inFlight = getCombineInFlightCount(berryTree, now);
    const maxInFlight = getMaxCombineInFlight(berryTree);
    const queueCount = berryTree.combineQueue.length;
    const canAffordDraft = canAffordBerryCombineSubmission(berryTree.combineDraft, game.items ?? {});
    const canTryCombine = draftFilled && canAffordDraft && (
        !combineInProgress
        || (hasCombineQueueUpgrade(berryTree) && inFlight < maxInFlight)
    );
    const showCombinePickerDuringProgress = combineInProgress && hasCombineQueueUpgrade(berryTree);
    const resolvedFarm = farmState ?? game.miltankFarmState ?? null;
    const farmLevel = resolvedFarm ? getMiltankFarmLevelSum(resolvedFarm) : 0;
    const ownedMilk = getAvailableMoomooMilk(Number(game.items?.moomoo_milk) || 0, resolvedFarm);
    const canPurchaseQueueUpgrade = canPurchaseBerryCombineQueueUpgrade(berryTree, ownedMilk, farmLevel);
    const combineQueueMaxLevel = BERRY_TREE.combineQueueMaxLevels;
    const combineQueueUpgradeCost = getCombineQueueUpgradeCostForNextLevel(berryTree);
    const plantQueueMaxLevel = BERRY_TREE.plantQueueMaxLevels;
    const plantQueueUpgradeCost = getPlantQueueUpgradeCostForNextLevel(berryTree);
    const canPurchasePlantQueueUpgrade = canPurchaseBerryPlantQueueUpgrade(berryTree, ownedMilk, farmLevel);
    const plantQueueKeys = berryTree.plantQueue;
    const plantQueueHeadKey = plantQueueKeys[0] ?? null;
    const combineDraftSlots = buildCombineSlotSnapshots(game, berryTree.combineDraft);
    const combinePendingSlots = combineInProgress && berryTree.pendingCombine
        ? buildCombineSlotSnapshotsFromSubmitted(game, berryTree.pendingCombine.submitted)
        : buildCombineSlotSnapshots(game, [null, null, null]);
    const combineQueuePreview = berryTree.combineQueue.map((entry) =>
        buildCombineSlotSnapshotsFromSubmitted(game, entry.submitted),
    );
    const combineQueueCapacityLabel = hasCombineQueueUpgrade(berryTree)
        ? farmT(
            game,
            'berryTree.combineQueueCapacity',
            '{current}/{max} analyses (active + file)',
            '{current}/{max} analyses (active + queue)',
            { current: inFlight, max: maxInFlight },
        )
        : null;

    const mulchOptions = Object.keys(BERRY_MULCHES).map((mulchKey) => {
        const owned = Math.max(0, Math.floor(Number(game.items?.[mulchKey]) || 0));
        const displayName = itemLabel(game, mulchKey);
        const description = itemDescription(game, mulchKey);
        const tooltip = buildBerryTreeMulchTooltipContent(game, {
            mulchKey,
            displayName,
            iconUrl: itemIconUrl(mulchKey),
            owned,
            description,
        });
        return {
            mulchKey,
            displayName,
            iconUrl: itemIconUrl(mulchKey),
            owned,
            canApply: owned > 0,
            tooltipTitle: tooltip.title,
            tooltipBody: tooltip.body,
        };
    });

    const plantOptions = [...berryTree.unlockedBerryKeys]
        .sort(compareBerryKeysByProductionTier)
        .map((berryKey) => {
        const overlay = buildFeticheBerryOverlay(berryKey, berryTasteByKey[berryKey] ?? null);
        const queueMeta = buildPlantQueueMeta(berryTree, berryKey, plantQueueKeys);
        return {
        berryKey,
        displayName: itemLabel(game, berryKey),
        iconUrl: itemIconUrl(berryKey),
        isActive: berryTree.activeCrop?.berryKey === berryKey,
        canQueue: queueMeta.canQueue,
        isQueued: queueMeta.isQueued,
        queuedCount: queueMeta.queuedCount,
        canAffordIngredients: hasBerryPlantIngredients(berryKey, game.items ?? {}),
        feticheTaste: berryTasteByKey[berryKey] ?? null,
        feticheStatHint: overlay.statHint,
        feticheStatEffect: overlay.statEffect,
        berryDescription: itemDescription(game, berryKey),
    };
    });

    const canPlantFromQueue = berryTree.plantQueueLevel > 0
        && !!plantQueueHeadKey
        && !berryTree.activeCrop?.berryKey
        && hasBerryPlantIngredients(plantQueueHeadKey, game.items ?? {});

    let plantQueueBlockedReason: string | null = null;
    if (plantQueueHeadKey && !canPlantFromQueue) {
        if (berryTree.activeCrop?.berryKey) {
            plantQueueBlockedReason = farmT(
                game,
                'berryTree.plantQueueActiveCrop',
                'Terminez la culture en cours avant de planter la file.',
                'Finish the current crop before planting from queue.',
            );
        } else if (!hasBerryPlantIngredients(plantQueueHeadKey, game.items ?? {})) {
            plantQueueBlockedReason = farmT(
                game,
                'berryTree.plantQueueMissingItems',
                'Ingrédients manquants pour planter {berry} depuis la file.',
                'Missing ingredients to plant {berry} from queue.',
                { berry: itemLabel(game, plantQueueHeadKey) },
            );
        }
    }

    return {
        ui,
        unlockedCount,
        totalCount,
        almanacProgressLabel: farmT(
            game,
            'berryTree.almanacProgress',
            '{unlocked}/{total} débloquées',
            '{unlocked}/{total} unlocked',
            { unlocked: unlockedCount, total: totalCount },
        ),
        almanacEntries: buildAlmanacEntries(game, berryTree, berryTasteByKey),
        combineDraft: combineDraftSlots,
        combineEligibleItemGroups: buildEligibleItemGroups(game),
        canTryCombine,
        combineInProgress,
        combineProgressPct: combineProgress.progressPct,
        combineProgressLabel: combineInProgress ? ui.combineProgress : null,
        combinePendingSlots,
        combineQueueCount: queueCount,
        combineQueueLabel: queueCount > 0
            ? farmT(game, 'berryTree.combineQueueLabel', '{count} analyse(s) en attente', '{count} analysis queued', { count: queueCount })
            : null,
        combineInFlightCount: inFlight,
        combineMaxInFlight: maxInFlight,
        combineQueueCapacityLabel,
        combineQueuePreview,
        combineQueueLevel: berryTree.combineQueueLevel,
        combineQueueMaxLevel,
        canPurchaseCombineQueueUpgrade: canPurchaseQueueUpgrade,
        combineQueueUpgradeLabel: berryTree.combineQueueLevel < combineQueueMaxLevel
            ? farmT(
                game,
                'berryTree.combineQueueUpgradeTitleLevel',
                'File d\'analyses ({level}/{max})',
                'Analysis queue ({level}/{max})',
                { level: berryTree.combineQueueLevel, max: combineQueueMaxLevel },
            )
            : null,
        combineQueueUpgradeCostLabel: berryTree.combineQueueLevel < combineQueueMaxLevel
            ? farmT(
                game,
                'berryTree.combineQueueUpgradeCost',
                '{milk} Lait Meumeu · ferme niv. {level}+',
                '{milk} Moomoo Milk · farm lv. {level}+',
                { milk: combineQueueUpgradeCost.moomoo_milk, level: combineQueueUpgradeCost.minFarmLevel },
            )
            : null,
        combineQueueUpgradeProgressLabel: berryTree.combineQueueLevel < combineQueueMaxLevel && !canPurchaseQueueUpgrade
            ? farmT(
                game,
                'berryTree.combineQueueUpgradeProgress',
                'Niveau ferme {farmLevel}/{levelReq} · Lait {milk}/{milkReq} (sac + pâturage)',
                'Farm level {farmLevel}/{levelReq} · Milk {milk}/{milkReq} (bag + pasture)',
                {
                    farmLevel,
                    levelReq: combineQueueUpgradeCost.minFarmLevel,
                    milk: ownedMilk,
                    milkReq: combineQueueUpgradeCost.moomoo_milk,
                },
            )
            : null,
        showCombinePickerDuringProgress,
        activeCrop: buildCropSnapshot(game, berryTree, now, ui),
        plantOptions,
        mulchOptions,
        canClaim: getBerryTreeHotspotStoredQty(berryTree) > 0,
        hotspotStoredQty: getBerryTreeHotspotStoredQty(berryTree),
        fertilizerActive,
        fertilizerMult: productionMult,
        fertilizerYieldMult: getBerryYieldMult(berryTree, now),
        bonusBerryChanceActive,
        boostEffectDetailLabel,
        boostRemainingMs,
        boostRemainingLabel: fertilizerActive
            ? farmT(game, 'berryTree.boostRemaining', 'Engrais — {time}', 'Mulch — {time}', {
                time: formatFarmDuration(boostRemainingMs, game),
            })
            : null,
        hasActiveCrop: !!berryTree.activeCrop?.berryKey,
        plantQueueLevel: berryTree.plantQueueLevel,
        plantQueueMaxLevel,
        plantQueueBerryKeys: plantQueueKeys,
        plantQueuePreview: plantQueueKeys.map((berryKey) => ({
            berryKey,
            displayName: itemLabel(game, berryKey),
            iconUrl: itemIconUrl(berryKey),
        })),
        plantQueueCapacityLabel: berryTree.plantQueueLevel > 0
            ? farmT(
                game,
                'berryTree.plantQueueCapacity',
                '{current}/{max} baies en file',
                '{current}/{max} berries queued',
                { current: plantQueueKeys.length, max: berryTree.plantQueueLevel },
            )
            : null,
        plantQueueLabel: plantQueueHeadKey
            ? plantQueueKeys.length > 1
                ? farmT(
                    game,
                    'berryTree.plantQueueMultiLabel',
                    'File : {berries}',
                    'Queue: {berries}',
                    { berries: plantQueueKeys.map((key) => itemLabel(game, key)).join(', ') },
                )
                : farmT(
                    game,
                    'berryTree.plantQueueLabel',
                    'Prochaine : {berry}',
                    'Next: {berry}',
                    { berry: itemLabel(game, plantQueueHeadKey) },
                )
            : null,
        canPlantFromQueue,
        plantQueueBlockedReason,
        canPurchasePlantQueueUpgrade,
        plantQueueUpgradeLabel: berryTree.plantQueueLevel < plantQueueMaxLevel
            ? farmT(
                game,
                'berryTree.plantQueueUpgradeTitleLevel',
                'File de plantation ({level}/{max})',
                'Plant queue ({level}/{max})',
                { level: berryTree.plantQueueLevel, max: plantQueueMaxLevel },
            )
            : null,
        plantQueueUpgradeCostLabel: berryTree.plantQueueLevel < plantQueueMaxLevel
            ? farmT(
                game,
                'berryTree.plantQueueUpgradeCost',
                '{milk} Lait Meumeu · ferme niv. {level}+',
                '{milk} Moomoo Milk · farm lv. {level}+',
                { milk: plantQueueUpgradeCost.moomoo_milk, level: plantQueueUpgradeCost.minFarmLevel },
            )
            : null,
        plantQueueUpgradeProgressLabel: berryTree.plantQueueLevel < plantQueueMaxLevel && !canPurchasePlantQueueUpgrade
            ? farmT(
                game,
                'berryTree.plantQueueUpgradeProgress',
                'Niveau ferme {farmLevel}/{levelReq} · Lait {milk}/{milkReq} (sac + pâturage)',
                'Farm level {farmLevel}/{levelReq} · Milk {milk}/{milkReq} (bag + pasture)',
                {
                    farmLevel,
                    levelReq: plantQueueUpgradeCost.minFarmLevel,
                    milk: ownedMilk,
                    milkReq: plantQueueUpgradeCost.moomoo_milk,
                },
            )
            : null,
        berryTasteByKey,
        feticheTasteHint,
    };
}

export function emptyBerryTreeSnapshot(game: GameRuntime): BerryTreeSnapshot {
    const ui = buildUi(game);
    return {
        ui,
        unlockedCount: 0,
        totalCount: BERRY_DEX_KEYS.length,
        almanacProgressLabel: farmT(
            game,
            'berryTree.almanacProgress',
            '{unlocked}/{total} débloquées',
            '{unlocked}/{total} unlocked',
            { unlocked: 0, total: BERRY_DEX_KEYS.length },
        ),
        almanacEntries: [...BERRY_DEX_KEYS].sort(compareBerryKeysByProductionTier).map((berryKey) => {
            const recipe = BERRY_TREE_RECIPES.find((r) => r.berryKey === berryKey);
            const len = recipe?.ingredients.length ?? 0;
            return {
                berryKey,
                name: itemLabel(game, berryKey),
                berryIconUrl: itemIconUrl(berryKey),
                unlocked: false,
                canPlant: false,
                isActiveCrop: false,
                canQueue: false,
                isQueued: false,
                queuedCount: 0,
                feticheTaste: null,
                feticheStatHint: null,
                feticheStatEffect: null,
                berryDescription: null,
                recipeSlots: Array.from({ length: len }, () => ({
                    revealed: false,
                    itemKey: null,
                    itemIconUrl: null,
                    itemName: null,
                    itemDescription: null,
                })),
            };
        }),
        combineDraft: [0, 1, 2].map((slotIndex) => ({
            slotIndex,
            itemKey: null,
            itemIconUrl: null,
            itemName: null,
        })),
        combineEligibleItemGroups: [],
        canTryCombine: false,
        combineInProgress: false,
        combineProgressPct: 0,
        combineProgressLabel: null,
        combinePendingSlots: [],
        combineQueueCount: 0,
        combineQueueLabel: null,
        combineInFlightCount: 0,
        combineMaxInFlight: BERRY_TREE.combineQueueMaxBase,
        combineQueueCapacityLabel: null,
        combineQueuePreview: [],
        combineQueueLevel: 0,
        combineQueueMaxLevel: BERRY_TREE.combineQueueMaxLevels,
        canPurchaseCombineQueueUpgrade: false,
        combineQueueUpgradeLabel: null,
        combineQueueUpgradeCostLabel: null,
        combineQueueUpgradeProgressLabel: null,
        showCombinePickerDuringProgress: false,
        activeCrop: null,
        plantOptions: [],
        mulchOptions: [],
        canClaim: false,
        hotspotStoredQty: 0,
        fertilizerActive: false,
        fertilizerMult: 1,
        fertilizerYieldMult: 1,
        bonusBerryChanceActive: 0,
        boostEffectDetailLabel: null,
        boostRemainingMs: 0,
        boostRemainingLabel: null,
        hasActiveCrop: false,
        plantQueueLevel: 0,
        plantQueueMaxLevel: BERRY_TREE.plantQueueMaxLevels,
        plantQueueBerryKeys: [],
        plantQueuePreview: [],
        plantQueueCapacityLabel: null,
        plantQueueLabel: null,
        canPlantFromQueue: false,
        plantQueueBlockedReason: null,
        canPurchasePlantQueueUpgrade: false,
        plantQueueUpgradeLabel: null,
        plantQueueUpgradeCostLabel: null,
        plantQueueUpgradeProgressLabel: null,
        berryTasteByKey: {},
        feticheTasteHint: null,
    };
}
